const teamLeader={init(){console.log("Team Leader Module Initialized"),this.bindEvents(),this.loadStats(),this.loadQueue(),this.renderKanban(),this.loadMembers();const user=JSON.parse(sessionStorage.getItem("user"));user&&(document.getElementById("userName").textContent=user.username),window.lucide&&window.lucide.createIcons()},bindEvents(){document.querySelectorAll(".nav-item").forEach(item=>{item.addEventListener("click",e=>{e.preventDefault();const section=item.getAttribute("data-section");"logout"!==section&&this.showSection(section)})}),document.getElementById("logoutBtn")?.addEventListener("click",()=>{logout()}),document.getElementById("initProjectForm")?.addEventListener("submit",e=>this.handleInitialization(e))},showSection(sectionId){document.querySelectorAll(".dashboard-section").forEach(s=>s.classList.remove("active")),document.querySelectorAll(".nav-item").forEach(n=>n.classList.remove("active"));const targetSection=document.getElementById(`${sectionId}Section`);targetSection&&(targetSection.classList.add("active"),document.querySelector(`[data-section="${sectionId}"]`)?.classList.add("active"),"projects"===sectionId&&this.loadProjectTable())},async loadStats(){try{const data=await api.get("/team-leader/dashboard-stats");document.getElementById("deptSavings").textContent=`₹${(data.total_savings||0).toLocaleString()}`,document.getElementById("activeCount").textContent=data.total_projects||0,document.getElementById("queueCount").textContent=data.queue_count||0}catch(err){console.error("Stats failed",err)}},async loadQueue(){const container=document.getElementById("validationQueueList");try{const queue=await api.get("/team-leader/queue");queue.length>0?container.innerHTML=queue.map(item=>`\n                    <div class="queue-item d-flex justify-content-between align-items-center p-3 border rounded-3 mb-2 bg-white shadow-sm">\n                        <div>\n                            <span class="badge bg-soft-primary text-primary mb-1">Stage ${item.stage}</span>\n                            <h6 class="mb-0">${item.title}</h6>\n                            <small class="text-muted">${item.type||""}</small>\n                        </div>\n                        <div class="d-flex gap-2">\n                             <button class="btn btn-sm btn-outline-primary" onclick="window.location.href='/projects/project-details.html?id=${item.id}'">Review</button>\n                            <button class="btn btn-sm btn-primary" onclick="teamLeader.confirmAction(${item.id}, 'proceed')">Validate & Proceed</button>\n                        </div>\n                    </div>\n                `).join(""):container.innerHTML='<p class="text-center text-muted m-0">No pending validations.</p>'}catch(err){console.error("Queue failed",err)}},async renderKanban(){const board=document.getElementById("kanbanBoard");if(!board)return;const stages=["1. Identification","2. Selection","3. Analysis","4. Causes","5. Root Cause","6. Data Analysis","7. Development","8. Implementation"];try{const projects=await api.get("/team-leader/projects");board.innerHTML=stages.map((s,idx)=>{const stageProjects=projects.filter(p=>p.stage===idx+1);return`\n                    <div class="kanban-col border rounded-3 p-2 bg-light" style="min-width: 220px;">\n                        <p class="fw-bold small mb-2 text-uppercase text-muted">${s}</p>\n                        <div class="kanban-cards d-flex flex-column gap-2">\n                            ${stageProjects.length>0?stageProjects.map(p=>`\n                                 <div class="card shadow-sm border-0 p-2 cursor-pointer" onclick="window.location.href='/projects/project-details.html?id=${p.id}'" style="cursor:pointer;">\n                                    <div class="small fw-bold text-truncate">${p.title}</div>\n                                    <div class="text-muted" style="font-size:0.7rem;">${p.uid||""}</div>\n                                    ${p.category?`<span class="badge bg-soft-primary text-primary mt-1" style="font-size:0.65rem;">${p.category}</span>`:""}\n                                </div>\n                            `).join(""):'<p class="text-muted small text-center m-0">—</p>'}\n                        </div>\n                    </div>\n                `}).join("")}catch(err){console.error("Kanban failed",err),board.innerHTML='<p class="text-danger">Failed to load project pipeline.</p>'}},async loadMembers(){const target=document.getElementById("memberChecklist");if(target)try{const users=await api.get("/team-leader/members");if(0===users.length)return void(target.innerHTML='<p class="text-muted small m-0">No department members found.</p>');target.innerHTML=users.map(u=>`\n                <div class="form-check">\n                    <input class="form-check-input" type="checkbox" value="${u.id}" name="members" id="m${u.id}">\n                    <label class="form-check-label small" for="m${u.id}">${u.username} <span class="text-muted">(${u.role})</span></label>\n                </div>\n            `).join("")}catch(err){console.error("Members load failed",err),target.innerHTML='<p class="text-danger small m-0">Failed to load members.</p>'}},async handleInitialization(e){e.preventDefault();const fd=new FormData(e.target),memberIds=Array.from(e.target.querySelectorAll('input[name="members"]:checked')).map(cb=>parseInt(cb.value)),payload={title:fd.get("title"),description:fd.get("description"),category:fd.get("category"),deadline:fd.get("deadline")||null,member_ids:memberIds},submitBtn=e.target.querySelector('button[type="submit"]');submitBtn.disabled=!0,submitBtn.textContent="Creating...";try{const result=await api.post("/projects",payload);alert("Project initialized successfully!");const modal=bootstrap.Modal.getInstance(document.getElementById("initProjectModal"));modal&&modal.hide(),result.project_id?window.location.href=`/projects/project-details.html?id=${result.project_id}`:window.location.reload()}catch(err){alert(err.message||"Initialization failed. Please try again.")}finally{submitBtn.disabled=!1,submitBtn.textContent="Create & Start Stage 1"}},async confirmAction(id,action){if(confirm("Are you sure you want to validate and proceed this project to the next stage?"))try{await api.post(`/team-leader/action/${id}/proceed`),this.loadQueue(),this.renderKanban(),this.loadStats()}catch(err){alert("Action failed: "+(err.message||""))}},async loadProjectTable(){const tbody=document.getElementById("projectsTableBody");if(tbody)try{const projects=await api.get("/team-leader/projects");tbody.innerHTML=projects.map(p=>`\n                <tr>\n                    <td><code>${p.uid||p.id}</code></td>\n                    <td><strong>${p.title}</strong></td>\n                    <td><span class="badge bg-primary">Stage ${p.stage}</span></td>\n                    <td><span class="badge ${"In Progress"===p.status?"bg-success":"Closed"===p.status?"bg-secondary":"bg-warning"}">${p.status}</span></td>\n                    <td>${p.members?p.members.map(m=>m.name).join(", "):"—"}</td>\n                     <td><button class="btn btn-sm btn-outline-primary" onclick="window.location.href='/projects/project-details.html?id=${p.id}'">Open</button></td>\n                </tr>\n            `).join(""),0===projects.length&&(tbody.innerHTML='<tr><td colspan="6" class="text-center text-muted">No projects found.</td></tr>')}catch(err){console.error("Project table load failed",err)}}};document.addEventListener("DOMContentLoaded",()=>{window.location.pathname.includes("dashboard-team-leader.html")&&teamLeader.init()});